      mmInk(g, mmCirclePts(lx, ly, 15, 18, 14, 0, 0.02, 331), { fill: mmMix('#e8eef5', '#ffe9b8', k), lw: MM_BG_LW });
      MM_SETS.steps.L = [{ x: lx, y: ly, r: 40, on: k }];
