  inWorld(() => { for (const pr of props) if (!(pr.st.z !== undefined || pr.p.inCast) && !pr.p.front && !pr.p.shotSpace) MM_PROPS[pr.p.name] && MM_PROPS[pr.p.name](g, t, pr.st); });
  for (const pr of props) if (pr.p.shotSpace) MM_PROPS[pr.p.name] && MM_PROPS[pr.p.name](g, t, pr.st);
