        const k = Math.min(1, st.onHead); st = Object.assign({}, st, { x: mmLerp(st.x, out.mook.headX, k), y: mmLerp(st.y, out.mook.headY - out.mook.R * 0.8, k) + (st.dy || 0), walkAmt: 0, shadow: 0 });
