  mmTitleWord(g, 'MOOK & MUSH', 640, 236, 96, t0 + 1.0, t, { seed: 12, col: MM.mkRed, stag: 0.07 });
  mmTitleWord(g, 'OR, EAT THE RECTANGLE', 640, 300, 30, t0 + 3.2, t, { seed: 13, col: MM.mkRed, stag: 0.03 });
  // the episode's own title is made of HER squares
  const k = mmSeg(u, 5.6, 7.4);
  if (k > 0) {
    const str = 'SQUARE EYES', cell = 13, adv = 6 * cell, total = str.length * adv - cell, x0 = 640 - total / 2, y0 = 326;
    [...str].forEach((ch, i) => {
      const rows = MM_PIX[ch]; if (!rows) return;
      for (let r = 0; r < 7; r++) for (let c = 0; c < 5; c++) if (rows[r] & (16 >> c)) {
        const idx = i * 35 + r * 5 + c, when = mmH2(idx, 17) * 0.8;
        const kk = mmSeg(k * 1.8 - when, 0, 0.2); if (kk <= 0) continue;
        const d = MM_DIG[String((i * 7 + r + c) % 10)];   // his number colours, one per square
        const sz = cell * 0.9 * mmBack(kk, 2);
        g.fillStyle = (i % 2) ? MM.mkTeal : MM.mkRed;
        g.fillRect(x0 + i * adv + c * cell + (cell - sz) / 2, y0 + r * cell + (cell - sz) / 2 - (1 - kk) * 30, sz, sz);
        g.strokeStyle = MM.ink; g.lineWidth = 2; g.strokeRect(x0 + i * adv + c * cell + (cell - sz) / 2, y0 + r * cell + (cell - sz) / 2 - (1 - kk) * 30, sz, sz);
      }
    });
  }
  // the three of them bounce in along the bottom
