  mmInk(g, [[-200, 660], [1480, 660]], { closed: false, lw: 2.2, ink: mmRGBA(MM.ink, 0.5) });
  const inK = (a, d) => mmOut(mmSeg(u, a, a + (d || 0.7)));
  const bounce = (a) => Math.abs(Math.sin((u - a) * 7)) * Math.max(0, 1 - (u - a) * 0.9) * 40;
  const km = inK(2.0), ku = inK(2.35), kt = inK(4.3, 0.9);
