  if (ku > 0) mushDraw(g, { x: mmLerp(-120, 610, ku), y: 668 - (ku < 1 ? bounce(2.35) : 0), h: 155, yaw: ku < 1 ? 1.2 : 0.15, t, seed: 2, eyes: {}, mouth: { shape: 'smile' }, arms: { R: [1.25, 1], L: [u > 3.3 && u < 5 ? 2.8 : 1.25, 1.1] } });
  if (kt > 0) tvDraw(g, { x: mmLerp(1500, 820, kt), y: 668, h: 130, t, seed: 3, flip: kt < 1 ? -1 : 1, walk: kt < 1 ? { ph: u * 2.2, amt: 1 } : null, screen: { mode: u > 6.3 ? 'face' : 'static', expr: 'happy' } });
  const out = mmSeg(u, (S.dur || 11.5) - 0.8, S.dur || 11.5);
