// ── flat colour, a black frame, a white flash ──
MM_SCN.black = function (g, t, S) { g.save(); g.setTransform(1, 0, 0, 1, 0, 0); g.fillStyle = S.col || '#08070b'; g.fillRect(0, 0, g.canvas.width, g.canvas.height); g.restore(); };

// ── S22 · THE END CARD: the title again, who made what, and what the eyes really saw ──
