    mmInk(g, mmCirclePts(cx + side * 0.08 * D, cy + 0.05 * D, 0.74 * D, 0.74 * D, 16, 0, 0.02, 106), { fill: MM.muFace, lw: lw * 0.7, amp: amp * 0.4, seed: 107, bk });
