    const list = [];
    for (let i = 0; i < n; i++) { const k = n > 1 ? i / (n - 1) : 0; list.push({ k, a: mmLerp(az[0], az[1], k) }); }
    const all = [];
    for (const e of list) for (const sd of [-1, 1]) all.push({ az: sd * e.a, k: e.k });
