  const r = G.headR * H, hyaw = yaw + (C.headTurn || 0);
  const lw = Math.max(1.6, H * 0.0096) * (C.lw || 1), amp = Math.max(0.35, H * 0.0025) * (C.wob === undefined ? 1 : C.wob);
  const Y = (f) => -(1 - f) * H;                     // a landmark (fraction of H down from the cap top) → body y (the soles at 0)
  const col = (part, side) => fnCol(TAB, part, side);
  const front = Math.cos(yaw), DB = C.dbg || {}, on = (k) => DB[k] !== 0;
  // (EP5) optional hooks for a character built on this body (Fianna): hk(name, {...}) calls C.hook[name](ctx). Off by default.
  const HK = C.hook || null, hk = (name, extra) => { if (HK && HK[name]) HK[name](Object.assign({ g, H, Y, yaw, lw, amp, bk, col, G, front, C }, extra || {})); };
