  const at = (u, v, w) => { const k = ht - v; return legXY(A[0] + D[0] * k + T[0] * u + S[0] * w, A[1] + D[1] * k + T[1] * u + S[1] * w, A[2] + D[2] * k + T[2] * u + S[2] * w); };
  const wo = P.bootOut / 2, lwa = lwB / a;
