  const wy = (wo - lwa) * 2 * a;
  const Q = [];
  for (const [u, v] of P.foot) {
    const wq = (u > 0.3 ? 0.45 : 1) * (wo - lwa);
    for (const w of [-wq, wq]) { const q = at(u > 0.2 ? u - lwa : u < -0.1 ? u + lwa : u, Math.max(v, 0) + lwa * (v < 0.05 ? 1 : 0.3), w); Q.push([q[0], q[1]]); }
  }
  for (const w of [-(wo - lwa), wo - lwa]) { const q = at(0, 0.45, w); Q.push([q[0], q[1]]); }
