// the eyes' mismatch at wonk = 1: [size ×, height + (× h), tilt (rad), squash (ry ×)] for his RIGHT (−1) and LEFT (+1) eye
const BR_WONK = { '-1': [1.16, -0.008, 0.16, 1.0], '1': [0.86, 0.011, -0.2, 1.1] };
