  const lg = { R: brCone(-G.legRoot[0], G.legRoot[1], G.legR0, -G.legTip[0], G.legTip[1], G.legR1), L: brCone(G.legRoot[0], G.legRoot[1], G.legR0, G.legTip[0], G.legTip[1], G.legR1) };
