    const T = G.torso, tAt = (u) => { if (u >= T[0][0]) return T[0]; if (u <= T[T.length - 1][0]) return T[T.length - 1];
      for (let i = 1; i < T.length; i++) if (u >= T[i][0]) { const k = (u - T[i][0]) / (T[i - 1][0] - T[i][0]); return T[i].map((v, j) => mmLerp(v, T[i - 1][j], k)); } return T[0]; };
