  bbGinger: '#D96533',   // 🎬 "his fiery unkempt beard" (1024) · "his impressive ginger chest hair" (1028): ginger (5 orange, toward 1 red)
  bbShirt: '#CF7B98',    // "his pink deep v shirt" (1027): his own pink, sampled from his TV Gurl / TV Boi drawings
  bbShorts: '#C3BEAE',   // 🎬 "Cargo shorts" (1028): khaki, the khaki sampled from his TV drawings
  bbSock: '#FFEDED',     // "high white socks" (1029): W, his white
  bbCork: '#C8A47A',     // 🎬 "birkenstock sandals" (1029): the cork sole
  bbStrap: '#7B4F36',    // 🎬 the two brown straps
  bbMug: '#FFEDED',      // 🎬 the "Mondays Man" mug (1025): W
  bbCoffee: '#7B4F36',   // 🎬
  bbEye: '#FFEDED',      // W, as his 2020 Mook's eyes
  // the rainbow cardigan (1027): one colour per digit of MOOK'S KEY (0 cyan · 1 red · 2 blue · 3 yellow · 4 green · 5 orange · 6 pink · 7 purple)
  bbK0: '#56D2DF',       // 🎬 0 cyan
  bbK1: '#EB6D83',       // R (his palette card)
