      const ch = [[0, 8.95, 0.24], [-0.26, 9.12, 0.21], [0.26, 9.1, 0.21], [-0.13, 8.7, 0.2], [0.13, 8.68, 0.2], [0, 8.45, 0.17], [-0.46, 9.3, 0.17], [0.46, 9.28, 0.17], [0, 9.25, 0.19]];
      const balls = [];
      for (const [x, v, rr] of ch) { const a = bbProfW(P, v); const az = Math.asin(mmClamp(x / a, -1, 1)); if (Math.abs(clampAz(az) - az) > 0.01) continue; const p = bbPr(onTorso(az, v, 1.02), yaw); if (p[2] < 0) continue; balls.push([p[0], p[1], rr * r * (0.55 + 0.45 * mmC01(p[2] / (D * a * r)))]); }
