    const bb = behindB(beardB); if (bb.length) bbBalls(g, bb, MM.bbGinger, lw, amp * 0.6, bk, 131, tongues.filter(q => q.d < hc[2] - 0.25 * r).map(q => bbStrand(q.pts, q.W)));
