    if (body === 'pit') { ch[3] = 0.27; ch[4] = 0.2; ch[5] = 0.24; ch[1] = 0.29; hp[3] = 0.18; hp[4] = 0.15; hp[1] = 0.27; hp[2] = -0.36; }
    const fat = body === 'dog' ? (P.fat || 1) : 1;
    for (const E of [ch, hp]) { E[3] *= fat; E[4] *= 1 + (fat - 1) * 0.4; E[5] *= fat; }     // wider and deeper; a little taller (his legs still show)
    // a fat dog's body still sits under the TV: the chest's top touches its underside at most
    const lift = Math.max(0, ch[1] + ch[4] - tvY0 + 0.005); ch[1] -= lift; hp[1] -= lift;
    const bodyY = ch[1], legTop = bodyY - ch[4] * 0.3;
