    K.line([[-0.32, hc + 1.14], [-0.08, hc + 2.2], [0, hc + 2.45], [0.08, hc + 2.2], [0.32, hc + 1.14]], { w: 0.75 });   // lapels
    K.line([[-0.3, hc + 1.5], [-0.52, hc + 1.42]], { w: 0.6 }); K.line([[0.3, hc + 1.5], [0.52, hc + 1.42]], { w: 0.6 }); // their notches
