  const yaw = C.yaw === undefined ? 1.2 : C.yaw, dir = Math.sin(yaw) >= 0 ? 1 : -1;
  const P = o.path || (() => ({ x: C.x, d: 0 })), p = P(C.t || 0), w = mmoPuffWalk(p.d, Object.assign({ h: C.h }, o));
