  const deckH = MMO_BOARD.top * R + MMO_BOARD.th * R * 0.5, hipH = 3.88 * R - P.drop * R + deckH;
  const Lmax = Math.sqrt(Math.max(0, Math.pow(0.9 * hose * 4.15 * R, 2) - hipH * hipH));
