    mmTube(g, [bb, pa], 0.016 * H, MM.fnGrey, lw * 0.8, { amp: amp * 0.4, seed: 641 + (sd === 'far'), bk });
    const ca = Math.cos(sl), sa = Math.sin(sl), hw = 0.034 * H * Math.max(0.25, side), hh = 0.011 * H;   // the pedal: level with the bike
