    const ell = (k, n, sd) => { const Q = []; for (let i = 0; i < n; i++) { const a = i / n * Math.PI * 2, x = Math.cos(a) * rx * k, y = Math.sin(a) * R * k; Q.push([c[0] + x * Math.cos(sl) - y * Math.sin(sl), c[1] + x * Math.sin(sl) + y * Math.cos(sl)]); } return Q; };
