  mmTube(g, [P(K.bar[0] + K.grip * 0.5, K.bar[1] - 0.005, -K.barW), bar, P(K.bar[0] + K.grip * 0.5, K.bar[1] - 0.005, K.barW)], tw * 0.75, MM.fnRed, lw, { amp, seed: 668, bk });   // the bar, end to end
