    const toRoad = o.off > 0 ? nm === 'left' : nm === 'right';
    if (!toRoad) return;
    dhRdWin(g, c, F, fl * 0.12, fl * 0.3, zf + h * 0.45, zf + h * 0.78, P.win, true);
