    const u0 = -hw + 2 * hw * i / 24, u1 = u0 + 2 * hw / 24, v0 = r ? z0 : z1 - 0.3, v1 = v0 + 0.3;
    dhRdFill(g, c, [dhRdW(o.s, u0, v0), dhRdW(o.s, u1, v0), dhRdW(o.s, u1, v1), dhRdW(o.s, u0, v1)].map(w => dhRdCw(c, w)), MM.ink);
