  p.save(); p.beginPath(); mmTrace(p, P, true); p.clip();
  mmInk(p, mmCirclePts(-W * 0.35, -H * 0.72, W * 0.62, H * 0.5, 22, -0.2, 0.06, 7), { fill: lit, lw: 0 });
  mmInk(p, mmCirclePts(W * 0.72, -H * 0.2, W * 0.6, H * 0.85, 22, 0.3, 0.05, 8), { fill: shade, lw: 0 });
  p.fillStyle = deep; p.fillRect(-W * 1.2, -H * 0.1, W * 2.4, H * 0.2);
  // clippings: short marker flicks, densest low on the pile
  p.lineCap = 'round'; p.beginPath();
  for (let i = 0; i < 90; i++) {
    const u = mmH2(i, 61) * 2 - 1, v = Math.pow(mmH2(i, 62), 0.7), x = u * W * Math.sqrt(1 - v * v) * 0.95, y = -v * H * 0.92;
    const a = -0.9 + mmH2(i, 63) * 1.8, L = 70 + mmH2(i, 64) * 90;
    p.moveTo(x, y); p.quadraticCurveTo(x + Math.cos(a) * L * 0.5, y + Math.sin(a) * L * 0.5 - 20, x + Math.cos(a) * L, y + Math.sin(a) * L);
  }
  p.lineWidth = MM_BG_LW * 0.8; p.strokeStyle = deep; p.stroke();
