    for (const wx of [-52, 52]) mmInk(p, mmRectPts(wx - 11, -32, wx + 11, 2, 7), { fill: '#6d6a74', lw: MM_BG_LW * 1.2 });
    mmInk(p, mmRectPts(-60, -86, 60, -26, 14), { fill: col, lw: MM_BG_LW * 1.2 });
    mmInk(p, mmCirclePts(0, -112, 26, 25, 14, 0, 0.02, 5), { fill: col, lw: MM_BG_LW * 1.2 });
