  const cols = o.cols || [DH_FX.grass[0], DH_FX.grass[1], DH_FX.grass[2], DH_FX.straw];
  const fogCol = o.fogCol || '#cfe6bd', fog = (o.fog === undefined ? 0.35 : o.fog) * k, hole = o.hole, dmin = o.dmin || 0, dmax = o.dmax === undefined ? 1 : o.dmax;
  const lay = [[], [], []], wts = [0.32, 0.3, 0.26, 0.12];
  const F = 640 / Math.tan((o.fov || 70) * Math.PI / 360), vpx = o.x === undefined ? 640 : o.x, vpy = o.y === undefined ? 330 : o.y;
  const wind = o.wind === undefined ? 1500 : o.wind, sgn = wind >= 0 ? -1 : 1, flowA = wind >= 0 ? Math.PI : 0;
