  const tau = dhWarp(t, o.slow) - dhWarp(t0, o.slow), rate = o.slow ? dhWarpRate(t, o.slow) : 1;
  if (tau < -0.16) return;
  const Sm = o.ms || (sp.road ? 1.2 : (o.s || 1.2)), R = 0.42 * Sm, cy = 1.4 * Sm, rb = 0.075 * Sm * (o.ballK || (sp.road ? 1.6 : 1.2)), inh = o.vel || [0, 0, 0];
  const G = o.G || DH_FX.G, e0 = o.e === undefined ? 0.62 : o.e, mu = o.mu === undefined ? 0.55 : o.mu;
  const dir = o.dir || [1, 0], V = o.v === undefined ? 4.2 : o.v, cols = o.cols || DH_FX.gum, bx = o.hitX === undefined ? -1 : o.hitX;
  const c0 = sp.p(0, cy, 0);
