    const px = Math.sin(ph) * Math.cos(th) * rr, py = Math.cos(ph) * rr * 0.8, pz = Math.sin(ph) * Math.sin(th) * rr;
    const vb = 1.6 + 2.6 * dhR(seed, i, 4), sh = 0.45 + 1.1 * dhR(seed, i, 5);
    const ik = o.ikS === undefined ? 0.5 + 0.8 * dhR(seed, i, 11) : 1 - o.ikS / 2 + o.ikS * dhR(seed, i, 11);   // the car's push: some faster than it, most slower (o.ikS: a narrower spread, so a cloud can ride WITH the car)
    const vx = dir[0] * V * sh + px / R * vb - bx * 0.8 + inh[0] * ik, vz = dir[1] * V * sh + pz / R * vb * 0.8 + (inh[2] || 0) * ik, vy = (0.8 + 3.4 * dhR(seed, i, 6) + py / R * vb) * (o.vyK === undefined ? 1 : o.vyK);
