  for (let i = L.length - 1; i >= 0; i--) { const p = edge(i, -L[i].tot / 2); g.lineTo(p[0], p[1]); }
  g.closePath(); g.lineWidth = (o.lw || 2.2) * 2; g.strokeStyle = MM.ink; g.stroke();
