  const sm = dhFxCv('m' + w + 'x' + h, w, h), x = sm.getContext('2d', { willReadFrequently: true });
  x.save(); x.setTransform(1, 0, 0, 1, 0, 0); x.globalCompositeOperation = 'copy'; x.globalAlpha = 1; x.imageSmoothingEnabled = true;
  x.drawImage(g.canvas, 0, 0, w, h); x.restore();
