  const sd = dhSdShDir(sun, o.s), kL = big ? Math.min(1, 1.6 / sun.L) : 1;     // buildings: a short, light shadow (ROAD's art call)
  const al = sd[0] * kL, ac = sd[1] * kL, out = [];
