  for (let q = Math.floor(sa / 2.5); q < sb / 2.5; q++) { const s = q * 2.5 + 0.9; if (segN(s).indexOf('fence') >= 0) items.push({ id: (q + 500000) >>> 0, d: dP, s, kind: 'post' }); }
