    const hM = it.kind === 'post' ? 1.0 : it.kind === 'reed' ? 1.0 + 0.5 * mmH2(it.id, 205) : it.kind === 'flower' ? 0.75 + 0.5 * mmH2(it.id, 205) : 0.55 + 0.4 * mmH2(it.id, 205);
