// ── THE FRAME ─────────────────────────────────────────────────────────────────────────────
function sbFrame(g, t, F) {
  const W = g.canvas.width, H = g.canvas.height, P = sbTod(F.tod);
  const sc = W / 1280;                            // the board may render smaller than the film: world stays 1280 x 720
  const cam = F.cam || { k: 1, cx: 640, cy: 360 };
  g.save();
  g.setTransform(1, 0, 0, 1, 0, 0);
  if (F.pov) { g.scale(sc, sc); sbPov(g, t, P, 1280, 720, F); g.restore(); return; }
  if (F.ins && SB_INS[F.ins.kind] && !F.ins.over) { g.scale(sc, sc); SB_INS[F.ins.kind](g, t, F.ins, 1280, 720); g.restore(); if (F.tint !== 0 && !F.ins.noTint) mmTint(g, P, 0.6); return; }
  g.scale(sc, sc); g.translate(640, 360); g.scale(cam.k, cam.k); g.translate(-cam.cx, -cam.cy);
  // the set
  const set = MM_SETS[F.set];
  const setO = { tod: P };
  if (set) set.bg(g, t, setO); else (SB_SETS[F.set] || SB_SETS.plain)(g, t, F, P);
  // props behind the cast, then the cast far to near (by y, or z), each with a soft contact shadow
  const items = [];
  for (const p of (F.props || [])) items.push({ y: p.z !== undefined ? p.z : p.y - (p.back ? 1000 : 0), draw: () => SB_PROPS[p.kind] && SB_PROPS[p.kind](g, t, p) });
  for (const c of (F.cast || [])) items.push({ y: c.z !== undefined ? c.z : c.y, c, draw: () => sbCast(g, t, c) });
  items.sort((a, b) => a.y - b.y);
  if (F.set !== 'space' && F.shadows !== false) for (const it of items) if (it.c && !it.c.rot && !it.c.noShadow && !SB_HOLO[it.c.who]) {
    const c = it.c, hh = c.h || SB_H[c.who] || 300, rx = hh * ({ mook: 0.2, mush: 0.3, tv: 0.42, puff: 0.3, otis: 0.5, barb: 0.17, bron: 0.2 }[c.who] || 0.22);
    g.fillStyle = 'rgba(52,40,72,0.16)'; g.beginPath(); g.ellipse(c.x, c.y + 2, rx, rx * 0.17, 0, 0, 7); g.fill();
  }
  for (const it of items) it.draw();
  if (set && set.fg) set.fg(g, t, setO);
  if (F.dbg) for (const d of F.dbg) { g.lineWidth = 3 / cam.k; g.strokeStyle = '#00c853'; g.beginPath(); g.arc(d[0], d[1], d[2], 0, 7); g.stroke(); g.beginPath(); g.arc(d[0], d[1], 4 / cam.k, 0, 7); g.stroke(); }
  g.restore();
  // the time of day over the whole frame (not in the hologram: it makes its own light)
  if (F.set !== 'space' && F.tint !== 0) mmTint(g, P, F.tint === undefined ? 1 : F.tint);
  // the near shoulder and over-the-frame inserts live in frame space, after the light
  g.save(); g.setTransform(sc, 0, 0, sc, 0, 0);
  if (F.ots) sbOts(g, t, F.ots, 1280, 720);
  if (F.ins && F.ins.over && SB_INS[F.ins.kind]) SB_INS[F.ins.kind](g, t, F.ins, 1280, 720);
  if (F.split) {                                  // 🎬 the split screen: a hard line down the middle
    g.fillStyle = MM.ink; g.fillRect(637, 0, 6, 720);
  }
  g.restore();
}

