  const gr = g.createLinearGradient(270, 0, 1010, 0); gr.addColorStop(0, 'rgba(0,0,0,0)'); gr.addColorStop(1, mmRGBA('#3d5f78', 0.35)); g.fillStyle = gr; g.fillRect(260, 190, 760, 340);
  for (let k = 0; k < 3; k++) { g.strokeStyle = mmRGBA(MM.ink, 0.55); g.lineWidth = 2.2; g.beginPath(); g.ellipse(268, 360, 70 + k * 34, 150 - k * 6, 0, -1.25, 1.25); g.stroke(); }
