  // the leaf: hinged on the north post, shut it points south along the run; open swings it into the yard
  const a = G.open, wdt = G.z1 - G.z0 - 0.1, hz = G.z1 - 0.07, dx = inner * Math.sin(a), dz = -Math.cos(a);
  const at = (u, y) => [X + dx * u, y, hz + dz * u];
  const leafRails = () => { for (const y of [0.35, H - 0.4]) ydFill(g, C, [at(0.02, y), at(wdt, y), at(wdt, y + 0.09), at(0.02, y + 0.09)], sh, null); ydLine(g, C, at(0.05, 0.4), at(wdt - 0.05, H - 0.35), Math.max(1.2, 0.025 * ydK(C, X, 0.7, hz)), sh); };
  if (!outside) leafRails();
