  if (!IN) { if (!ydPoly(g, C, top)) { g.restore(); return; } g.clip(); }
  ydFill(g, C, bot, floorC, null);
  // the floor's things: the deep end darker, three curved steps at the shallow end, the drain, cracks, THE NAMES
  for (let i = 0; i < 4; i++) ydFill(g, C, ydPoolDeep(p, mmLerp((p.x0 + p.x1) / 2 - 1.5, p.x1 - 1.2, i / 3)), mmRGBA('#3d5f78', 0.06), null);   // the deep end darker
