  // the tile course just under the coping, and the bowl's bottom edge
  g.strokeStyle = mmRGBA('#ffffff', 0.45); g.lineWidth = 1.6; ydPath(g, C, top.map(q => [q[0], -0.16, q[2]]).concat([[top[0][0], -0.16, top[0][2]]])); g.stroke();
  g.strokeStyle = mmRGBA(ink, 0.6); g.lineWidth = lw * 0.8; ydPath(g, C, bot.concat([bot[0]])); g.stroke();
