    for (const [dx, dz] of [[-0.14, 0.14], [0.14, 0.14], [-0.14, -0.14], [0.14, -0.14]]) ydLine(g, C, [x + dx * 0.6, h, z + dz * 0.6], [x + dx, 0, z + dz], Math.max(2, 0.03 * ydK(C, x, 0.3, z)), '#6d6a74');
