    const x = be[0], z = be[1]; ydShadow(g, C, x, z, 0.9, 0.6, 0.27);
    for (const dx of [-0.55, 0.55]) ydBox(g, C, { x0: x + dx - 0.1, x1: x + dx + 0.1, y0: 0, y1: 0.22, z0: z - 0.1, z1: z + 0.1 }, { front: '#c0685a', side: '#a5574b', top: '#b9614f' });
