    ydLine(g, C, B, apex, Math.max(2, 0.035 * ydK(C, B[0], 1.4, B[2])), '#6d6a74');
    const under = (C.x - rc[0]) * A[0] + (C.y - rc[1]) * A[1] + (C.z - rc[2]) * A[2] < 0;
    const tris = ring.map((a, i) => { const b = ring[(i + 1) % U.n]; return { P: [a, b, apex], col: cols[i % 3], d: ydDepth(C, (a[0] + b[0] + apex[0]) / 3, (a[2] + b[2] + apex[2]) / 3) }; });
    tris.sort((P1, P2) => P2.d - P1.d);
    const lw = YD_LW(), shade = U.light ? U.light : null;
