    const wall = (a, b, h, cols, rows, seed, lit, skip) => {
      for (let r = 0; r < rows; r++) for (let c = 0; c < cols; c++) {
        if (skip && skip.some(([sc, sr]) => sc === c && sr === r)) continue;
        const u0 = c / cols, u1 = (c + 1) / cols, v0 = r / rows * h, v1 = (r + 1) / rows * h, L = (u) => [mmLerp(a[0], b[0], u), 0, mmLerp(a[2], b[2], u)];
        const p0 = L(u0), p1 = L(u1);
        pane([[p0[0], v0, p0[2]], [p1[0], v0, p1[2]], [p1[0], v1, p1[2]], [p0[0], v1, p0[2]]], seed + r * cols + c, lit);
      }
    };
    const gable = (z, seed, lit) => {                    // the gable's triangle: two windows under the ridge
      const A = [B.x0, B.eave, z], M = [xm, B.ridge, z], Bb = [B.x1, B.eave, z], mid = [xm, B.eave, z];
      pane([A, mid, M], seed, lit); pane([mid, Bb, M], seed + 1, lit);
    };
    const roof = (side, seed, lit) => {                 // a slope of the roof: three long panes
      const xe = side < 0 ? B.x0 : B.x1;
      for (let k = 0; k < 3; k++) { const za = mmLerp(B.z0, B.z1, k / 3), zb = mmLerp(B.z0, B.z1, (k + 1) / 3);
        pane([[xe - side * 0.0, B.eave, za], [xe, B.eave, zb], [xm, B.ridge, zb], [xm, B.ridge, za]], seed + k, lit); }
    };
