  for (const c of (o.cast || [])) items.push({ d: ydDepth(C, c.x, c.z) + (c.dz || 0), f: () => c.draw(g, C, P, t), pool: !!c.pool, x: c.x, z: c.z, fp: c.fp, r: c.r, y0: c.y0, who: c.who, name: c.who || c.name, h: c.hM || c.h || (typeof A4H !== 'undefined' && A4H[c.who]) || 1.2 });
