  fianna:   { lat: 0.045, a: 0.21, b: 0.1, ra: 0.46, rb: 0.15, vRun: 1.9, lift: 0.05, rlift: 0.17, st: 0.6, rst: 0.36, hip: 0.5, ank: 0.115, leg: 0.385, heel: 0.04, lean: 0.03, rlean: 0.18, arm: 0.28 },
