  ydFill(g, C, [[D.x0, D.y1, D.z0], [D.x1, D.y1, D.z0], [D.x1, D.y1, D.z1], [D.x0, D.y1, D.z1]], mmMix(C6_ONYX, '#000000', 0.2), null);
