  for (const rr of [2.4, 2.55]) { ydPath(g, C, ringAt(L.y0 + 0.003, rr).concat([ringAt(L.y0 + 0.003, rr)[0]])); g.strokeStyle = mmRGBA(C6_BRASS, 0.8); g.lineWidth = Math.max(1.2, l * 0.7); g.stroke(); }
