  let C = Object.assign({ x: 0, y: C6.floor + 1.4, z: 1.5, F: 900, sx: 0, sy: 0, yaw: 0, pitch: 0 }, o.C || {});
  if (o.aim) C = ydAim(C, o.aim);
  const so = Object.assign({ t }, o);
  g.save(); g.lineCap = 'round'; g.lineJoin = 'round'; g.fillStyle = '#100c14'; g.fillRect(0, 0, 1280, 720);
  let items = [], after = [];
  if (o.set === 'hall') { c6HallShell(g, C, P, so); c6HallFloor(g, C, P, so); items = c6HallItems(so); after = [c6HallBeams]; }
  else if (o.set === 'dine') { c6DineShell(g, C, P, so); items = c6DineItems(so); after = [c6DineLight]; }
  else if (o.set === 'lib') { c6LibShell(g, C, P, so); items = c6LibItems(so); after = [c6LibBeam]; }
  else if (o.set === 'dorm') { c6DormShell(g, C, P, so); items = c6DormItems(so); after = [c6DormLight]; }
  items = items.concat(o.cast || []);
  const S = items.map(c => ({ d: ydDepth(C, c.x, c.z) + (c.dz || 0), f: () => c.draw(g, C, P, t) })); S.sort((a, b) => b.d - a.d); for (const s of S) s.f();
