    const z = i * 2.3 + mmH2(i, s + 62) * 2.0, x = s * (DW.road - 0.25 + mmH2(i, s + 63) * (mmH2(i, s + 64) < 0.5 ? 0.3 : 6.5));
    if (ydDepth(C, x, z) < 0.8) continue;
