// ── the lamppost speaker, MAYOR MCCOOL's poster on its post (EP4 scene 4's poster, the clump on his teeth) ──
function e5PosterArt(g, tt, clump) {
  mmInk(g, [[0, 0], [110, 0], [110, 140], [0, 140]], { fill: '#f6efd9', lw: 1.6 });
  g.fillStyle = '#c9504f'; g.fillRect(0, 0, 110, 9); g.fillRect(0, 131, 110, 9);
  mmCaps(g, 'MAYOR MCCOOL SAYS', 55, 24, { size: 8.5, align: 'c', w: 1.6, seed: 5, col: '#3c3a52' });
  const lip = [[8, 46], [30, 40], [55, 43], [80, 40], [102, 46], [92, 70], [72, 82], [55, 84], [38, 82], [18, 70]];
  mmInk(g, lip, { fill: '#e07a86', lw: 1.8, poly: false });
  const mouth = [[16, 50], [55, 49], [94, 50], [86, 66], [55, 76], [24, 66]];
  mmInk(g, mouth, { fill: '#7a2f3a', lw: 1.2, poly: false });
  g.save(); g.beginPath(); mmTrace(g, mouth, true, false); g.clip();
  for (let i = 0; i < 8; i++) { const x0 = 18 + i * 9.4; mmInk(g, [[x0, 48], [x0 + 9.0, 48], [x0 + 8.8, 61], [x0 + 0.4, 61.5]], { fill: '#ffffff', lw: 0.9 }); }
  for (let i = 0; i < 7; i++) { const x0 = 25 + i * 8.6; mmInk(g, [[x0, 63], [x0 + 8.2, 63], [x0 + 8.0, 74], [x0 + 0.3, 74]], { fill: '#f4f1ea', lw: 0.8 }); }
  g.restore();
  if (clump > 0) { const k = clump;
    mmInk(g, mmCirclePts(58, 55, 13 * k, 8 * k, 14, 0.2, 0.25, 41), { fill: '#7fbf5a', lw: 1.4, poly: false });
    g.strokeStyle = '#4f8e38'; g.lineWidth = 1.4; for (let i = 0; i < 7; i++) { const a = -2.8 + i * 0.45; g.beginPath(); g.moveTo(58, 55); g.lineTo(58 + Math.cos(a) * 18 * k, 55 + Math.sin(a) * 13 * k); g.stroke(); } }
  mmCaps(g, 'THE ANNUAL', 55, 98, { size: 10, align: 'c', w: 2, seed: 6, col: '#2f5a3a' });
  mmCaps(g, 'SPRING LAWN CARE', 55, 112, { size: 10, align: 'c', w: 2, seed: 7, col: '#2f5a3a' });
  mmCaps(g, 'COMPETITION', 55, 126, { size: 10, align: 'c', w: 2, seed: 8, col: '#2f5a3a' });
}
// L = { x, z, talk (0..1 the horns pulse), crack (0..1), poster (true), clump (0..1) }
function e5Lamp(g, C, P, L, t) {
  const B = ydPt(C, L.x, 0, L.z), Tp = ydPt(C, L.x, 4.3, L.z); if (!B || !Tp) return;
  const w0 = 0.09 * B[2], w1 = 0.06 * Tp[2], lw = Math.max(2, 0.02 * Tp[2]);
  mmInk(g, [[B[0] - w0, B[1]], [Tp[0] - w1, Tp[1]], [Tp[0] + w1, Tp[1]], [B[0] + w0, B[1]]], { fill: '#56606f', lw, amp: 0.4, seed: 931 });
  mmInk(g, mmRectPts(Tp[0] - 0.16 * Tp[2], Tp[1] - 0.42 * Tp[2], Tp[0] + 0.16 * Tp[2], Tp[1] - 0.02 * Tp[2], 0.04 * Tp[2]), { fill: '#e9e4d6', lw, amp: 0.3, seed: 932 });
  mmInk(g, [[Tp[0] - 0.24 * Tp[2], Tp[1] - 0.42 * Tp[2]], [Tp[0], Tp[1] - 0.62 * Tp[2]], [Tp[0] + 0.24 * Tp[2], Tp[1] - 0.42 * Tp[2]]], { fill: '#56606f', lw, amp: 0.3, seed: 933 });
  if (L.poster !== false) { const pc = ydPt(C, L.x, 1.55, L.z); if (pc) { const s = 0.62 * pc[2] / 110;
    g.save(); g.translate(pc[0] - 55 * s, pc[1] - 70 * s); g.scale(s, s); e5PosterArt(g, t, L.clump || 0); g.restore(); } }
  const hb = ydPt(C, L.x, 3.75, L.z); if (!hb || typeof dhA2Horn !== 'function') return;
  const kk = Math.max(L.crack || 0, (L.talk || 0) * 1.2);
  dhA2Horn(g, hb[0] + 0.5 * hb[2], hb[1] + 0.12 * hb[2], 0.4 * hb[2], 0.32, kk, t);
  dhA2Horn(g, hb[0] - 0.5 * hb[2], hb[1] + 0.12 * hb[2], 0.4 * hb[2], Math.PI - 0.32, kk, t + 0.3);
  if (L.clumpHorn) e5Clump(g, C, L.x + 0.45, 3.95, L.z, 0.14, 77);
}

