  const at = (n) => [Z.x + (mmH2(Z.seed, 10 + n) - 0.5) * 2.4, 0.55 + 0.4 * mmH2(Z.seed, 30 + n), Z.z + (mmH2(Z.seed, 50 + n) - 0.5) * 2.4];
