    ydFill(g, C, [[-DW.road, 0.002, z], [DW.road, 0.002, z], [DW.road, 0.002, z + 20], [-DW.road, 0.002, z + 20]], mmMix(P.road || '#b4b7b6', '#8f8a98', 0.2), null);
    for (let d = z; d < z + 20; d += 6) ydLine(g, C, [0, 0.003, d], [0, 0.003, d + 2.6], Math.max(1, 0.12 * ydK(C, 0, 0, d + 1.3)), mmRGBA('#f3efe6', 0.45));   // the centre line, faded
