    const Q = B.poly; for (let i = 0; i < Q.length; i++) { const a = Q[i], b = Q[(i + 1) % Q.length], ex = b[0] - a[0], ez = b[1] - a[1], L = Math.hypot(ex, ez) || 1, nx = ez / L, nz = -ex / L;   // outward
      if (!clip(nx * (O[0] - a[0]) + nz * (O[2] - a[1]) - pad, nx * d[0] + nz * d[2])) return false; }
