    for (let y = gy - gh; y > top - R.R * 3; y -= R.R * 0.14) { const odd = Math.round((gy - y) / (R.R * 0.14)) % 2; g.beginPath(); if (odd) g.ellipse(R.x, y, R.R * 0.04, R.R * 0.08, 0, 0, 7); else { g.moveTo(R.x - R.R * 0.05, y); g.lineTo(R.x + R.R * 0.05, y); } g.stroke(); }
