    g.fillStyle = mmRGBA('#2f78c8', 0.72); g.beginPath(); g.moveTo(R.x - R.R, R.y + R.R); for (let x = -R.R; x <= R.R; x += R.R / 12) g.lineTo(R.x + x, lvl + Math.sin(x / R.R * 9 + T * 3) * R.R * 0.025); g.lineTo(R.x + R.R, R.y + R.R); g.closePath(); g.fill();
