    if (T < s.t0 - 0.05 || T > s.t1 + 0.6) continue;
    const pos = (tt) => { const u = mmC01((tt - s.t0) / (s.t1 - s.t0)), e = 1 - Math.pow(1 - u, 1.6);
      return [mmLerp(s.a[0], s.b[0], e), mmLerp(s.a[1], s.b[1], e) + (s.arc || 0) * Math.sin(Math.PI * e), mmLerp(s.a[2], s.b[2], e)]; };
