const o9Paint = (b) => { b.items.sort((p, q) => p[0] - q[0]); for (const [, fn] of b.items) fn(); };

// ═══ DALE · a beaver-chicken ✏️ (his 2020 drawing, built as drawn) ══════════════════════════════════════════════
//   A tall yellow neck-and-head in one, two big round eyes up top (blue pupils), a pointed purple beak with a line
