// ═══ NOVA · a jellyfish who is a lantern 🎬 (the formula: a jellyfish + a lantern; the feeling: a nightlight) ═══════
//   A bell, cyan | violet, with a brass cap and a ring handle on top (a lantern); she walks on her two long arms like a
//   stork walks, the frills trailing; when the others are scared she glows (C.glow 0..1: a flat pale-yellow halo).
function novaDraw(g, C) {
  const b = o9Base(C, 'nova'), K = O9K, H = b.H, glow = C.glow === undefined ? 0.5 : C.glow, t = b.t;
  g.save(); g.translate(C.x, C.y); g.rotate(C.lean || 0); g.scale(C.sx || 1, C.sy || 1);
  const bell = [0, 0.66, 0], BR = [0.2, 0.27, 0.19];
  // the halo (flat, behind everything)
  if (glow > 0.02) b.items.push([-9 * H, () => { const p = b.pr(bell[0], bell[1] - 0.03, bell[2]); g.save(); g.globalAlpha = 0.85;
    mmInk(g, mmCirclePts(p[0], p[1], (0.2 + 0.14 * glow) * H, (0.2 + 0.13 * glow) * H, 30, 0, 0.04, 211), { fill: K.nvGlow, amp: b.amp * 0.5, seed: 211, bk: b.bk, poly: false }); g.restore(); }]);
  // the frills: four thin ribbons from under the bell. (EP9, ✅ 🗣 call 51f a) C.hold, a world point: the frill nearest it
  //   (or C.holdFrill, 0..3) reaches out (stretching, cartoon) and wraps twice round what's there: Lofty's string.
  //   C.reach 0..1 (default 1): from hanging to reaching · C.wrap 0..1 (default 1): the coil closing
  const tip = o9Local(C, C.hold); let iHold = -1;
  if (tip) { if (C.holdFrill !== undefined) iHold = C.holdFrill; else { let best = Infinity; for (let i = 0; i < 4; i++) { const az = (i + 0.5) / 4 * Math.PI * 2, r = b.pr(Math.sin(az) * 0.11, 0.52, Math.cos(az) * 0.1), dd = Math.hypot(r[0] - tip[0], r[1] - tip[1]); if (dd < best) { best = dd; iHold = i; } } } }
  for (let i = 0; i < 4; i++) { const az = (i + 0.5) / 4 * Math.PI * 2, root = [Math.sin(az) * 0.11, 0.52, Math.cos(az) * 0.1];
    if (i === iHold) { const r = b.pr(root[0], root[1], root[2]), col = i % 2 ? K.nvCyan : K.nvViolet, Q = [], rc = C.reach === undefined ? 1 : mmC01(C.reach), wr = C.wrap === undefined ? 1 : mmC01(C.wrap);
      const P1 = [r[0], r[1] + 0.12 * H], P2 = [tip[0] - (tip[0] - r[0]) * 0.25, tip[1] - (tip[1] - r[1]) * 0.25 + 0.04 * H];
      for (let j = 0; j <= 12; j++) { const u = j / 12, v = 1 - u, x = v * v * v * r[0] + 3 * v * v * u * P1[0] + 3 * v * u * u * P2[0] + u * u * u * tip[0], y = v * v * v * r[1] + 3 * v * v * u * P1[1] + 3 * v * u * u * P2[1] + u * u * u * tip[1];
        const hq = b.pr(root[0] + Math.sin(t * 2 + i + u * 5) * 0.025 * u, root[1] - u * 0.36, root[2] - 0.02 * u);    // (where it hangs)
        Q.push([mmLerp(hq[0], x + Math.sin(t * 2 + i + u * 5) * 0.008 * H * u * (1 - u), rc), mmLerp(hq[1], y, rc)]); }
      b.items.push([r[2] - 0.05 * H, () => { mmTube(g, Q, 0.018 * H, col, b.lw * 0.7, { amp: b.amp * 0.3, seed: 221 + i, bk: b.bk });
        if (wr > 0.01) for (const k of [-1, 1]) { const A = [], e = Q[Q.length - 1]; for (let j = 0; j <= 8; j++) { const a = j / 8 * Math.PI * wr; A.push([e[0] + Math.cos(a) * 0.026 * H, e[1] + k * 0.013 * H + Math.sin(a) * 0.01 * H]); }
          mmTube(g, A, 0.016 * H, col, b.lw * 0.7, { amp: 0, seed: 225 + k, bk: b.bk }); } }]);
      continue; }
    const P = []; for (let j = 0; j <= 6; j++) { const u = j / 6; P.push([root[0] + Math.sin(t * 2 + i + u * 5) * 0.025 * u, root[1] - u * 0.36, root[2] - 0.02 * u]); }
    const PP = P.map(p => b.pr(p[0], p[1], p[2])), d = PP[0][2];
    b.items.push([d - 0.05 * H, () => mmTube(g, PP.map(p => [p[0], p[1]]), 0.018 * H, i % 2 ? K.nvCyan : K.nvViolet, b.lw * 0.7, { amp: b.amp * 0.3, seed: 221 + i, bk: b.bk })]); }
  // the two walking arms: long, thin, a stork's bend, a curl at the foot (violet under the cyan side, cyan under the violet)
  // (2026-10-20, EP13's climb out of the hatch: C.legs = { R: { kn, ft }, L: { kn, ft } } in her body units puts her knee and foot
  //   there; inert unless given)
  for (const sd of [-1, 1]) { const LG = C.legs && C.legs[sd < 0 ? 'R' : 'L'], hip = [sd * 0.08, 0.52, 0.02], kn = (LG && LG.kn) || [sd * 0.1, 0.27, -0.06], ft = (LG && LG.ft) || [sd * 0.1, 0.02, 0.04];
    const P = [hip, kn, ft].map(p => b.pr(p[0], p[1], p[2])), col = sd < 0 ? K.nvViolet : K.nvCyan;
    b.items.push([P[2][2] - 0.04 * H, () => { mmTube(g, P.map(p => [p[0], p[1]]), 0.03 * H, col, b.lw * 0.85, { amp: b.amp * 0.4, seed: 231 + sd, bk: b.bk });
      const c = P[2]; mmInk(g, mmCirclePts(c[0] + 0.012 * H * (b.cy >= 0 ? sd : -sd), c[1] - 0.012 * H, 0.03 * H, 0.016 * H, 12, 0, 0, 233), { fill: col, lw: b.lw * 0.8, amp: 0, seed: 233, bk: b.bk, poly: false }); }]); }
  // the bell (a dome, scalloped hem), the brass cap and the handle, the face
  b.items.push([0, () => {
    const p = b.pr(bell[0], bell[1], bell[2]), hw = Math.sqrt(Math.pow(BR[0] * b.cy, 2) + Math.pow(BR[2] * b.sy, 2)) * H, hh = BR[1] * H, sil = [];
    for (let i = 0; i <= 24; i++) { const a = Math.PI + i / 24 * Math.PI; sil.push([p[0] + Math.cos(a) * hw, p[1] + Math.sin(a) * hh]); }
    const sc = 5; for (let i = 0; i < sc; i++) { const x0 = p[0] + hw - i / sc * 2 * hw, x1 = p[0] + hw - (i + 1) / sc * 2 * hw; for (let j = 1; j <= 6; j++) { const a = j / 6 * Math.PI; sil.push([mmLerp(x0, x1, (1 - Math.cos(a)) / 2), p[1] + Math.sin(a) * 0.035 * H]); } }
    const sa = Math.sin(mmSeamAng(b.yaw)), inner = []; for (let i = 0; i <= 8; i++) { const v = 1 - i / 8; inner.push([p[0] + sa * BR[2] * Math.sqrt(1 - v * v) * H, p[1] - v * hh]); } inner.push([p[0] + sa * BR[2] * H, p[1] + 0.04 * H]);
    const [cl, cr] = o9Pair(b.yaw, K.nvCyan, K.nvViolet);
    o9SplitShape(g, b, sil, inner, cl, cr, 241);
    // the brass cap + ring handle
    const cp = b.pr(0, bell[1] + BR[1] - 0.005, 0); mmInk(g, mmCirclePts(cp[0], cp[1], 0.055 * H * (0.6 + 0.4 * Math.abs(b.cy)) + 0.02 * H * Math.abs(b.sy), 0.022 * H, 14, 0, 0, 243), { fill: K.nvBrass, lw: b.lw * 0.85, amp: 0, seed: 243, bk: b.bk, poly: false });
    const hr = 0.05 * H, sw = Math.sin(t * 1.3) * 0.08; mmInk(g, mmCirclePts(cp[0], cp[1] - hr * 0.95, hr * Math.max(0.2, Math.abs(Math.cos(b.yaw + sw))), hr * 0.85, 18, 0, 0, 244), { closed: true, lw: b.lw * 1.6, ink: MM.ink, amp: 0, seed: 244, bk: b.bk, poly: false });
    mmInk(g, mmCirclePts(cp[0], cp[1] - hr * 0.95, hr * Math.max(0.2, Math.abs(Math.cos(b.yaw + sw))), hr * 0.85, 18, 0, 0, 244), { closed: true, lw: b.lw * 0.8, ink: K.nvBrass, amp: 0, seed: 244, bk: b.bk, poly: false });
    const lk = C.look || [0, 0];
    for (const sd of [-1, 1]) { const az = sd * 0.42, f = b.fv(az); if (f < 0.05) continue;
      const q = o9On(b, bell, BR, az, 0.42, 1.0), rx = 0.06 * H * Math.max(0.3, Math.pow(f, 0.6)), ry = 0.062 * H;
      o9Eye(g, b, q, rx, ry, { seed: 247 + sd, look: lk, ring: sd < 0 ? K.nvViolet : K.nvCyan, pupil: 0.018 * H, lid: C.lid, lidCol: sd < 0 ? K.nvCyan : K.nvViolet }); }
    if (b.fv(0) > 0.2) { const q = o9On(b, bell, BR, 0, 0.2); o9Mouth(g, b, q, 0.024 * H, C, 249); }
  }]);
  o9Paint(b); g.restore();
  return { top: C.y - (bell[1] + BR[1] + 0.1) * H };
}

// ═══ KINGPIN · a king penguin who is a bowling pin 🎬 (the formula: a penguin + a tenpin; he can't be knocked down) ═══
