  const addSolid = (P) => { const id = solid.length; solid.push(P); const xs = P.map(p => p[0]), zs = P.map(p => p[1]);
    for (let i = Math.floor(Math.min(...xs) / cell); i <= Math.floor(Math.max(...xs) / cell); i++) for (let j = Math.floor(Math.min(...zs) / cell); j <= Math.floor(Math.max(...zs) / cell); j++) { const k = sk(i, j); if (!SH.has(k)) SH.set(k, []); SH.get(k).push(id); } };
