  const free = (x, z, r) => { if (x > -42 - r && x < 110 + r && z > -50 - r && z < 50 + r) return false; if (x > 128 - r && x < 535 && z > -350 && z < 30) return false;
    if (x > 52 - r && x < 135 + r && Math.abs(z - T10.inst.z) < 66) return false; if (x > -32 && x < 18 && z > -305 && z < -244) return false;
    if (x > -172 - r && x < -114 + r && z > -124 - r && z < -80 + r) return false; if (Math.hypot(x - T10.clip.c[0], z - T10.clip.c[1]) < T10.clip.R + r + 1) return false; return true; };
  // ── mowers: in the back yards of some lived-in lots (📖 "People in Mowersville take their lawns too seriously"), and on the
