  const X = T10.tex, K = X.ppm, cv = document.createElement('canvas'); cv.width = Math.round((X.x1 - X.x0) * K); cv.height = Math.round((X.z1 - X.z0) * K);
  const g = cv.getContext('2d'), Cc = T10.col, c = T10.c, pal = t10Pal(), E = { pal }, drw = pal === 'drawing', WP = WFC.pal[pal];
