function sf11StarFields(o) { o = o || {}; const br = Math.sin((o.T || 0) * 1.3);
  return { pose: { R: [0.95, -0.3 + 0.02 * br, 0, { spread: 1.3 }], L: [0.95, -0.3 - 0.02 * br, 0, { spread: 1.3 }] }, legFoot: { R: [-0.2, -0.01, 0], L: [0.2, -0.01, 0] },
    blink: o.eyes === undefined ? 1 : 1 - o.eyes, mouth: o.mouth || 'smile', brows: -0.6, sy: 1 + 0.012 * br, sx: 1 - 0.006 * br }; }
