  const dir = Math.hypot(q[0] - p[0], q[1] - p[1]) > 1e-4 ? Math.atan2(q[0] - p[0], -(q[1] - p[1])) : (o.dir || 0), H = A4H[who];
  const foot = (s0) => { const f = phi + s0, k = Math.floor((f + K.w) / 2), c = f - 2 * k;   // c: −w … 2 − w (0 = mid-stance)
    if (c < K.w) return [0, 0.04 * (who === 'rose' ? 1.2 : 1), -c * K.step / H];                                         // planted
    const u = (c - K.w) / (2 - 2 * K.w), up = K.lift * Math.pow(Math.sin(Math.PI * u), 0.7), z = (-K.w + 2 * K.w * mmSmooth(u)) * K.step - 0.5 * K.step * Math.sin(Math.PI * u) * (1 - u);
    return [0, 0.04 + up, z / H]; };
  const fR = foot(0), fL = foot(1), mix = (a) => [a[0], mmLerp(0.04, a[1], run), a[2] * run], bob = K.bob * Math.pow(Math.sin(Math.PI * phi), 2) * run, sw = Math.cos(Math.PI * phi) * run;
  const F = Object.assign({ foot: { R: mix(fR), L: mix(fL) }, fwd: K.lean * run, pose: { R: [0.2, 0.55, K.arm * sw, { fist: 0.6 }], L: [0.2, 0.55, -K.arm * sw, { fist: 0.6 }] } }, o.f || {});
  if (who === 'gil') { F.worry = 1; F.pose = { R: [0.25, 0.5, 0.5 * sw], L: [0.25, 0.5, -0.5 * sw] }; F.geo = { tail: [[0, 0.13, -0.1], [0, 0.16, -0.25], [0.02 * Math.sin(T * 9), 0.2, -0.42], [0.05 * Math.sin(T * 9 + 1), 0.24, -0.6], [0.07 * Math.sin(T * 9 + 2), 0.27, -0.76]], tailW: [0.03, 0.026, 0.021, 0.015, 0.01] }; }
  if (who === 'rose') { F.mouth = F.mouth || 'line'; F.look = F.look || [0, -0.1]; }
  const y = (o.floor || ((x, z) => lk11GY(x, z)))(p[0], p[1]);
  return sf11Rig(who, [p[0], y + bob, p[1]], dir, F, { dz: o.dz || 0, shadow: y });
