  const G = n13Gal(), gk = mmC01((sN - 0.45) / 0.5), nrm = n13Cross(G.u, G.v), gd = (th, off) => [0, 1, 2].map(j => Math.cos(th) * G.u[j] + Math.sin(th) * G.v[j] + nrm[j] * off);
