// ═══ THE TOWN FROM THE AIR AT NIGHT ═══
// ⚠ (2026-10-15) THE FIRST TOWN FRAME ON A FRESH PAGE: GeoV's loop guard allows 3,000,000 loop steps a frame, and the town's caches
//   (the plan, the ground textures, the wild, the lamps: ~1.2 M steps) built inside a frame that then draws the whole town tripped
//   it ("a loop ran away") — every export part opens a fresh page. n13Warm builds them once and gives the frame a fresh count
//   (__lc is the guard's counter, in scope for every block: GeoV compiles the blocks into each clip).
function n13Warm() {
  if (window.__n13warm) return;
  t10Plan(); t10Tex(); t10WildTex(); t10Wild(); t10Blocks(); n13Lamps(); t10ClipFaces(); t10InstFaces();
  window.__n13warm = 1; if (typeof __lc !== 'undefined') __lc = 0;
}
function e13Town(g, t, cam, o) {
  n13Warm(); o = o || {}; const T = o.T === undefined ? t : o.T, N = n13State(T, o);
  const items = n13LampItems(N).concat(o.line === false ? [] : n13Line(Object.assign({ T }, o.line || {})), o.items || []);
  const sky0 = ydSky; window.__N13 = N;
  ydSky = function (gg, CC, PP) { n13SkyBase(gg, CC, PP, N); n13Sky(gg, CC, PP, N); };
  // (the items go in the TOWN's sort, so a house hides a lamp behind it; e10Sky's own items are drawn over the whole town)
  try { return e10Sky(g, t, cam, { T, tod: 'night', traffic: false, tint: 0, items: [], ground: { n13: N, hazeCol: 'rgb(' + (N.navy || N13.navy).join(',') + ')', folk: false, mowers: false, blockDz: o.blockDz, items }, after: o.after, roll: o.roll }); }
  finally { ydSky = sky0; window.__N13 = null; }
}

// ═══ THE GROOVE MACHINE AT NIGHT (📄 "the tie-dye hull lit by its own little lights"): its body as EP12's gm12Item (on the
//   night's layer, so the night falls on it like on the town), then its own lights on top: the headlamps and their beams
//   (o.beams), the tail lamps, a string of little bulbs along both roof shoulders (o.bulbs), the cab lit warm through the
//   windshield. o: gm12Item's o (or a function of t), + lights 0..1 ═══
