    const nose = gmW(B, gmFace(0, 1.2)), tail = gmW(B, [-G.L / 2, 1.0, 0]), noseOn = gmDot(B.f, gmSub(cam, nose)) > 0, tailOn = gmDot(B.f, gmSub(cam, tail)) < 0;
