      const tip = (dr, dv) => gmW(B, [G.L / 2 + 13, 0.92 + dv - 1.2, r * 1.6 + dr]), Q = [tip(-1.6, -0.6), tip(1.6, -0.6), tip(1.6, 1.4), tip(-1.6, 1.4)].map(p => ydPt(C, ...p));
