// ── _geo/episodes/ep05/blocks/mm_pool5.js
// ═══════════════════════════════════════════════════════════════════════════════════════════════════════════
// mm_pool5.js · EP5 · THE OLD PAINT (🎬 Claude, 2026-10-08). Needs mm_yard3.js (the pool, YD.namesAfter).
//   📖 "–Mook –Finley–Puff –Mush–, is painted on the inside of the lagoon shaped pool" (the book). 🎬 EP5: under their names,
//   older paint, faded: a big FIANNA and, beside it, a small wobbly FIN, and two handprints, one big, one tiny. Mook's back
//   wheel scrapes a flake off; he scratches more away with his thumbnail.
//   p5OldPaint(o) → sets YD.namesAfter for one frame: o = { k (0..1: how much is scratched away), wheel (0..1: the first
//   flake from the wheel), lit (0..1: a little sun on it) }. Call it before ydScene; p5OldPaintOff() after.
// ═══════════════════════════════════════════════════════════════════════════════════════════════════════════
const P5 = { x: -0.6, z: -0.7, w: 5.0, h: 1.8, sx: -1.0, sz: 0.3 };   // sx, sz: where the first flake comes off (from the patch's centre)          // the scratched patch: centred on the floor at the names' far end (x from the pool's middle)
function p5Floor(p, x) { return -ydPoolDepth(x) + 0.008; }
function p5OldPaint(o) {
  YD.namesAfter = (g, C, p, zc) => {
    const k = mmC01(o.k || 0), wh = mmC01(o.wheel || 0); if (k <= 0 && wh <= 0) return;
    const cx = (p.x0 + p.x1) / 2 + P5.x;
    // the patch: a ragged band of bare old paint, growing from where the wheel took the first flake
    const R = []; const n = 28;
    for (let i = 0; i < n; i++) { const a = i / n * Math.PI * 2, rag = 0.82 + 0.18 * mmH2(i, 7);
      const ex = Math.max(wh * 0.18, k) * P5.w / 2 * rag, ez = Math.max(wh * 0.12, k * 0.9 + 0.1 * wh) * P5.h / 2 * rag;
      const x = cx + P5.sx * (1 - k) + Math.cos(a) * ex, z = zc + P5.z + P5.sz * (1 - k) + Math.sin(a) * ez; R.push([x, p5Floor(p, x), z]); }
    g.save(); if (!ydPoly(g, C, R)) { g.restore(); return; } g.clip();
    ydFill(g, C, R, '#bfd9e3', null);                                   // the old floor colour under the paint
    const word = (str, x0, dz, size, col, a, seed, tr) => {
      const m = 0.0105; let acc = -mmCapsWidth(str, size, tr) / 2;
      for (let i = 0; i < str.length; i++) { const w = mmCapsWidth(str[i], size, tr), x = x0 + (acc + w / 2) * m; acc += w; const y = p5Floor(p, x) + 0.001;
        const sl = (ydPoolDepth(x + 0.05) - ydPoolDepth(x - 0.05)) / 0.1, ul = Math.hypot(1, sl);
        ydPlane(g, C, [x, y, zc + P5.z + dz], [1 / ul, -sl / ul, 0], [0, 0, 1], 0.4, () => {
          g.scale(m, -m); g.globalAlpha = a;
          mmCaps(g, str[i], 0, 0, { size, w: size * 0.2, align: 'c', seed: seed + i, jit: size > 30 ? 1.4 : 3.2, bk: 0, each: () => ({ col, rot: (mmH2(seed + i, 3) - 0.5) * (size > 30 ? 0.12 : 0.4) }) }); }); }
    };
    word('FIANNA', cx - 0.45, -0.2, 54, '#d88aa0', 0.85, 900, -0.5);                 // big, a teenager's letters, faded to rose
    word('FIN', cx + 1.42, -0.3, 26, '#8fb0de', 0.95, 940, 0);                    // small and wobbly: a four-year-old's, faded blue
    // the two handprints: a big one and a tiny one, side by side
    const hand = (x, z, s, col) => { const y = p5Floor(p, x) + 0.002;
      ydFill(g, C, ydGroundEllipse(x, z, 0.075 * s, 0.09 * s, null, y, 12), col, null);
      for (let f = 0; f < 5; f++) { const a = -0.9 + f * 0.45 + (f === 4 ? 0.5 : 0), d = (f === 4 ? 0.1 : 0.15) * s;
        ydFill(g, C, ydGroundEllipse(x + Math.sin(a) * d, z - Math.cos(a) * d * 0.9, 0.022 * s, 0.04 * s, [Math.sin(a), -Math.cos(a)], y, 8), col, null); } };
    hand(cx + 1.15, zc + P5.z + 0.25, 1.0, mmRGBA('#d88aa0', 0.85));
    hand(cx + 1.42, zc + P5.z + 0.28, 0.55, mmRGBA('#8fb0de', 0.9));
    g.restore();
    // the patch's edge: the kids' paint lifting in curls
    g.save(); g.lineWidth = 1.4; g.strokeStyle = mmRGBA(MM.ink, 0.6); ydPath(g, C, R.concat([R[0]])); g.stroke(); g.restore();
  };
}
function p5OldPaintOff() { YD.namesAfter = null; }

