      for (let i = 0; i < 5; i++) { g.beginPath(); g.ellipse(mmH2(i, 31) * B.w, -mmH2(i, 32) * B.h, 0.12 + 0.1 * mmH2(i, 33), 0.03, mmH2(i, 34) - 0.5, 0, 7); g.fill(); }
      g.globalAlpha = 1; g.save(); g.scale(0.01, 0.01);
