  const fl = (x, z) => mmaMcY(x, z, {}), vx = T.ax - T.cx, vz = T.az - T.cz, vl = Math.hypot(vx, vz), fx = vx / vl, fz = vz / vl, rx = -fz * T.face, rz = fx * T.face;
