  x.fillStyle = ink; x.beginPath(); x.arc(0.168 * W, 0.205 * H, 3 * S, 0, 7); x.arc(0.232 * W, 0.2 * H, 3 * S, 0, 7); x.fill();
  pen([[0.13, 0.3], [0.1, 0.62], [0.11, 0.66], [0.3, 0.66], [0.29, 0.3]], 2);
  for (let i = 0; i < 11; i++) { const u = 0.115 + i * 0.016; pen([[u + 0.005, 0.31], [u, 0.66]], 1.2); }
  pen([[0.29, 0.34], [0.33, 0.25], [0.335, 0.2]], 1.8); pen([[0.335, 0.2], [0.325, 0.18]], 1.4); pen([[0.335, 0.2], [0.345, 0.18]], 1.4); pen([[0.335, 0.2], [0.355, 0.195]], 1.4);
  pen([[0.13, 0.36], [0.08, 0.52], [0.09, 0.56]], 1.8);
  pen([[0.17, 0.66], [0.165, 0.84], [0.14, 0.86]], 1.8); pen([[0.25, 0.66], [0.255, 0.84], [0.28, 0.86]], 1.8);
  pen([[0.02, 0.87], [0.4, 0.865]], 1.2);
