  pen([[0.36, 0.7], [0.62, 0.36]], 1.4); pen([[0.585, 0.36], [0.62, 0.36], [0.61, 0.4]], 1.4);
  pen([[0.6, 0.28], [0.44, 0.38]], 1.4); pen([[0.46, 0.35], [0.44, 0.38], [0.475, 0.39]], 1.4);
