// ═══ NOODLES DiMARCO · "The Alphabet, As I See It" — after his own synesthetic alphabet (2026): a letter's place is its
//   colour (A = 0 cyan, B = 1 red … J = 9 black); from K = 10 on, two digits, the tile split on the diagonal, tens above,
//   units below. A classroom chart for the orphans' dorm. (D, N and X carry his yellow 3; the set's guard turns it brass,
//   ✅ his call, 2026-10-21.) ──
MMA_PAINT.alphabet = (x, W, H, pc, R, p) => {
  const S = Math.min(W, H) / 512, cols = 6, pad = W * 0.04, top = H * 0.12, gap = W * 0.018, tw = (W - pad * 2 - gap * (cols - 1)) / cols, th = Math.min(tw, (H - top - pad - gap * 4) / 5);
  x.fillStyle = '#1e1c22'; x.fillRect(0, 0, W, H);
  mmCaps(x, 'THE ALPHABET, AS I SEE IT', W / 2, top * 0.62, { size: 20 * S, w: 2.6 * S, col: '#f4f1ea', align: 'c', jit: 0.15, seed: 2 });
  const rr = (x0, y0, w, h, r) => { x.beginPath(); x.moveTo(x0 + r, y0); x.arcTo(x0 + w, y0, x0 + w, y0 + h, r); x.arcTo(x0 + w, y0 + h, x0, y0 + h, r); x.arcTo(x0, y0 + h, x0, y0, r); x.arcTo(x0, y0, x0 + w, y0, r); x.closePath(); };
  for (let i = 0; i < 26; i++) {
    const c = i % cols, r = Math.floor(i / cols), x0 = pad + c * (tw + gap), y0 = top + r * (th + gap), d = String(i);
    x.save(); rr(x0, y0, tw, th, tw * 0.12); x.clip();
    if (d.length === 1) { x.fillStyle = MM_DIG[d]; x.fillRect(x0, y0, tw, th); }
    else { x.fillStyle = MM_DIG[d[0]]; x.beginPath(); x.moveTo(x0, y0); x.lineTo(x0 + tw, y0); x.lineTo(x0, y0 + th); x.closePath(); x.fill();
      x.fillStyle = MM_DIG[d[1]]; x.beginPath(); x.moveTo(x0 + tw, y0); x.lineTo(x0 + tw, y0 + th); x.lineTo(x0, y0 + th); x.closePath(); x.fill(); }
    x.restore();
    x.strokeStyle = 'rgba(0,0,0,0.35)'; x.lineWidth = 1.5 * S; rr(x0, y0, tw, th, tw * 0.12); x.stroke();
    mmCaps(x, String.fromCharCode(65 + i), x0 + tw / 2, y0 + th * 0.62, { size: th * 0.42, w: th * 0.075, col: '#ffffff', out: th * 0.03, align: 'c', jit: 0.08, seed: i });
    mmCaps(x, d.length === 1 ? d : d[0] + '-' + d[1], x0 + tw / 2, y0 + th * 0.86, { size: th * 0.11, w: th * 0.022, col: '#ffffff', out: th * 0.012, align: 'c', jit: 0.05, seed: 40 + i });
  }
};

// ═══ NOODLES DiMARCO · "Two Friends (a sketch)" — after his own pencil drawing of Mook and Mush (@dumbsean, 8 May
//   2018): the short round one with one big eye and one small, a little 'w' of a mouth, buttons on a string and a hash on
//   its front; the tall one with two big eyes and long legs. Two and a half years before anything moved. Pinned up in
